begin;
update employee_profiles set archived_at=null where id='15000000-0000-4000-8000-000000fa0008';
update workspace_memberships set status='active', role='manager', role_id='bbbb6f06-0472-4230-984c-d58335df8b74' where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and user_id='e8336f72-d18e-41bd-bb8d-fac7b8f74353';
set constraints all immediate;
-- Zeynep (admin) builds a two-location draft
select 'A1 zeynep acquire', public.acquire_schedule_edit_session_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1','2026-09-28','blank')->>'status';
select 'A2 create PA', left(public.mutate_schedule_edit_shift_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'create',null,null,jsonb_build_object('location_id','6b98d6ab-c5c3-433f-8b8c-1c6c1a8c437c','employee_id','2768f70d-bd57-45b1-aecf-2dbce98bae8a','job_id','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','scheduled_date','2026-09-29','start_time','09:00','end_time','11:00','time_basis','explicit'),gen_random_uuid())::text,30) from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'A3 create SV', left(public.mutate_schedule_edit_shift_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'create',null,null,jsonb_build_object('location_id','bed21ebc-985f-432d-8f38-9d546cb3d13c','employee_id','2768f70d-bd57-45b1-aecf-2dbce98bae8a','job_id','1a39b1fe-3213-438c-a4c5-5de3b6eacf60','scheduled_date','2026-09-30','start_time','12:00','end_time','16:00','time_basis','explicit'),gen_random_uuid())::text,30) from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'A4 zeynep save', public.save_schedule_edit_session_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'Week plan',null,null,false)->>'id' from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'A5 draft shifts by location', l.name, count(*) from schedule_draft_shifts ds join schedule_drafts d on d.id=ds.draft_id join locations l on l.id=ds.location_id where d.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and d.name='Week plan' group by l.name;
-- Ayse opens the draft: session holds only Kadikoy
select 'A6 ayse acquire draft', public.acquire_schedule_edit_session_service('e8336f72-d18e-41bd-bb8d-fac7b8f74353','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1','2026-09-28','draft',(select id from schedule_drafts where workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and name='Week plan'))->>'status';
select 'A7 session shifts', count(*) from schedule_edit_session_shifts ss join schedule_edit_sessions s on s.id=ss.session_id where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.status='active';
-- Zeynep takes over and saves into the same draft
select 'A8 zeynep takeover', public.takeover_schedule_edit_session_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id)->>'status' from schedule_edit_sessions s where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active';
select 'A9 zeynep save same draft', public.save_schedule_edit_session_service('52977b4c-157c-4a73-9c16-83f55c5419df','6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1',s.id,s.revision,'Week plan',d.id,d.revision,false)->>'id' from schedule_edit_sessions s, schedule_drafts d where s.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and s.week_start='2026-09-28' and s.status='active' and d.workspace_id=s.workspace_id and d.name='Week plan';
select 'A10 draft shifts by location after', l.name, count(*) from schedule_draft_shifts ds join schedule_drafts d on d.id=ds.draft_id join locations l on l.id=ds.location_id where d.workspace_id='6ea5d512-bc7f-4cf3-aad4-2f0815de0fa1' and d.name='Week plan' group by l.name;
rollback;
